// Arma el lote de correos bancarios que se manda a POST /ingest.
//
// LA TRAMPA, y costo cinco semanas de correos perdidos en silencio: el nodo
// IMAP entrega el header From ENTERO ("BCP Notificaciones <notificaciones@
// notificacionesbcp.com.pe>"), no la direccion pelada que entregaba el Gmail
// Trigger que este workflow usaba antes de migrar. La version anterior de
// este codigo comparaba ese string completo contra BANCOS -- que solo tiene
// direcciones peladas -- asi que NUNCA matcheaba y descartaba todos los
// correos: el POST salia con la lista vacia e ingest respondia
// {received:0}. Y las ejecuciones se veian "success" igual, porque
// tecnicamente no fallaba nada, simplemente no quedaba nada que mandar. Por
// eso direccion() saca siempre lo de adentro de los <>.

const BANCOS = new Set([
  'service@intl.paypal.com',
  'notificaciones@notificacionesbcp.com.pe',
  'servicioalcliente@netinterbank.com.pe',
  'no-reply@operaciones.agora.pe',
  'bancadigital@scotiabank.com.pe',
  'no-reply@servicioalcliente.sip.pe',
]);

/** Direccion pelada en minusculas, venga como string RFC5322 u objeto. */
function direccion(campo) {
  if (!campo) return '';
  if (Array.isArray(campo.value) && campo.value[0]) {
    return String(campo.value[0].address || '').toLowerCase();
  }
  const crudo = typeof campo === 'string' ? campo : campo.text || '';
  const entreAngulos = crudo.match(/<([^>]+)>/);
  return (entreAngulos ? entreAngulos[1] : crudo).trim().toLowerCase();
}

/** Repara el mojibake del nodo IMAP.
 *
 *  El cuerpo llega decodificado como Latin-1 cuando en realidad son bytes
 *  UTF-8, asi que "Credito" con tilde llega como "CrÃ©dito" (U+00C3 U+00A9
 *  en lugar de U+00E9). El asunto NO sufre esto -- se decodifica por otra
 *  via (RFC 2047) y llega bien --, solo el cuerpo. Y alcanza para romperlo
 *  todo: los regex del parser en Rust buscan "Cr[ée]dito", no matchean, y
 *  el correo termina en discarded_events como si fuera propaganda.
 *
 *  Solo se toca si aparece la firma del mojibake, y con `fatal: true` para
 *  que un texto que ya estaba bien se devuelva intacto en vez de quedar
 *  peor: si la conversion no da UTF-8 valido, era un falso positivo. */
function repararUtf8(s) {
  // Â-Ã seguido de un byte de continuacion: la firma de UTF-8
  // leido como Latin-1. Escapes explicitos a proposito -- este codigo viaja
  // por JSON y por psql antes de llegar a n8n, y un literal acentuado aqui
  // Firma del mojibake: \u00C2-\u00C3 (los bytes altos de UTF-8 vistos
  // como Latin-1) seguidos de un byte de continuacion. Va con escapes y no
  // con caracteres acentuados literales porque este codigo viaja por JSON y
  // por psql antes de llegar a n8n.
  if (!s || !/[\u00C2-\u00C3][\u0080-\u00BF]/.test(s)) return s;
  try {
    const bytes = Uint8Array.from(s, (c) => c.charCodeAt(0) & 0xff);
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    return s;
  }
}

/** Cuerpo en texto plano. En los correos de BCP `textPlain` viene PRESENTE
 *  pero vacio (son single-part HTML), asi que el fallback no es opcional. */
function cuerpo(j) {
  if (j.textPlain) return repararUtf8(j.textPlain);
  const html = j.textHtml || j.html || '';
  if (html) return repararUtf8(String(html).replace(/<[^>]+>/g, ' '));
  return j.snippet || '';
}

function texto(v) {
  return typeof v === 'string' ? v : (v && v.text) || '';
}

const emails = [];

for (const { json: j } of $input.all()) {
  const sender = direccion(j.From || j.from || j.headers?.from);
  if (!BANCOS.has(sender)) continue;

  // gmail_msg_id es la clave de deduplicacion en la base (unique junto con
  // user_id) y el nodo IMAP no lo expone arriba del todo: vive en metadata.
  // Sin esto todos los correos colisionarian entre si.
  const msgId =
    j.metadata?.['message-id'] ||
    j.messageId ||
    j.id ||
    (j.attributes?.uid ? `uid:${j.attributes.uid}` : '');

  const fecha = j.date || j.internalDate || j.Date;
  const epoch = Number(fecha);

  emails.push({
    gmail_msg_id: msgId,
    sender,
    subject: texto(j.Subject || j.subject || j.headers?.subject),
    text: cuerpo(j),
    received_at: fecha
      ? new Date(isNaN(epoch) ? fecha : epoch).toISOString()
      : new Date().toISOString(),
  });
}

return [{ json: { emails } }];
